90	impl<Client, Prefetcher> FileHandleType<Client, Prefetcher>
91	where
92	    Client: ObjectClient + Send + Sync,
93	    Prefetcher: Prefetch,
94	{
95	    async fn new_write_handle(
96	        lookup: &LookedUp,
97	        ino: InodeNo,
98	        flags: i32,
99	        pid: u32,
100	        fs: &S3Filesystem<Client, Prefetcher>,
101	    ) -> Result<FileHandleType<Client, Prefetcher>, Error> {
102	        // We can't support O_SYNC writes because they require the data to go to stable storage
103	        // at `write` time, but we only commit a PUT at `close` time.
104	        if flags & (libc::O_SYNC | libc::O_DSYNC) != 0 {
105	            return Err(err!(libc::EINVAL, "O_SYNC and O_DSYNC are not supported"));
106	        }
107	
108	        let handle = match fs.superblock.write(&fs.client, ino, lookup.inode.parent(), pid).await {
109	            Ok(handle) => handle,
110	            Err(e) => {
111	                return Err(e.into());
112	            }
113	        };
114	        let key = lookup.inode.full_key();
115	        let handle = match fs.uploader.put(&fs.bucket, key).await {
116	            Err(e) => {
117	                return Err(err!(libc::EIO, source:e, "put failed to start"));
118	            }
119	            Ok(request) => FileHandleType::Write(UploadState::InProgress { request, handle }.into()),
120	        };
121	        metrics::increment_gauge!("fs.current_handles", 1.0, "type" => "write");
122	        Ok(handle)
123	    }
124	
125	    async fn new_read_handle(lookup: &LookedUp) -> Result<FileHandleType<Client, Prefetcher>, Error> {
126	        if !lookup.stat.is_readable {
127	            return Err(err!(
128	                libc::EACCES,
129	                "objects in flexible retrieval storage classes are not accessible",
130	            ));
131	        }
132	        lookup.inode.start_reading()?;
133	        let handle = FileHandleType::Read {
134	            request: Default::default(),
135	            etag: match &lookup.stat.etag {
136	                None => return Err(err!(libc::EBADF, "no E-Tag for inode {}", lookup.inode.ino())),
137	                Some(etag) => ETag::from_str(etag).expect("E-Tag should be set"),
138	            },
139	        };
140	        metrics::increment_gauge!("fs.current_handles", 1.0, "type" => "read");
141	        Ok(handle)
142	    }
143	}
