146	enum UploadState<Client: ObjectClient> {
147	    InProgress {
148	        request: UploadRequest<Client>,
149	        handle: WriteHandle,
150	    },
151	    Completed,
152	    // Remember the failure reason to respond to retries
153	    Failed(libc::c_int),
154	}
