160	            Self::Completed => return Err(err!(libc::EIO, "upload already completed for key {:?}", key)),
161	            Self::Failed(e) => return Err(err!(*e, "upload already aborted for key {:?}", key)),
162	        };
163	
164	        match upload.write(offset, data).await {
165	            Ok(len) => Ok(len as u32),
166	            Err(e) => {
167	                // Abort the request.
168	                match std::mem::replace(self, Self::Failed(e.to_errno())) {
169	                    UploadState::InProgress { handle, .. } => {
170	                        if let Err(err) = handle.finish_writing() {
171	                            // Log the issue but still return the write error.
172	                            error!(?err, ?key, "error updating the inode status");
173	                        }
174	                    }
175	                    Self::Failed(_) | Self::Completed => unreachable!("checked above"),
176	                };
177	                Err(e.into())
178	            }
179	        }
180	    }
181	
