95	impl Superblock {
96	    /// Create a new Superblock that targets the given bucket/prefix
97	    pub fn new(bucket: &str, prefix: &Prefix, config: SuperblockConfig) -> Self {
98	        let mount_time = OffsetDateTime::now_utc();
99	
100	        let root = Inode::new(
101	            ROOT_INODE_NO,
102	            ROOT_INODE_NO,
103	            String::new(),
104	            prefix.to_string(),
105	            InodeKind::Directory,
106	            InodeState {
107	                // The root inode never expires because there's no remote to consult for its
108	                // metadata, and it always exists.
109	                stat: InodeStat::for_directory(mount_time, NEVER_EXPIRE_TTL),
110	                write_status: WriteStatus::Remote,
111	                kind_data: InodeKindData::default_for(InodeKind::Directory),
112	                lookup_count: 1,
113	            },
114	        );
115	
116	        let mut inodes = HashMap::new();
117	        inodes.insert(ROOT_INODE_NO, root);
118	
